import "jsr:@supabase/functions-js/edge-runtime.d.ts";
// Versión EXACTA (no `@2`): esta función corre con service_role; un rango podría
// resolver otra versión en un deploy futuro. Al subir, revisar contra la última 2.x.
import { createClient } from "jsr:@supabase/supabase-js@2.110.8";
import { interpretarAutorizacionContacto } from "./autorizacion-contacto.ts";
import { indexarDestinosImportacion } from "./destinos.ts";
import {
  type CategoriaResultadoImportacion,
  clasificarErrorPuerta,
  clasificarRespuestaPuerta,
  type RespuestaPuerta,
} from "./resultado-importacion.ts";
import { etiquetaPropia } from "./catalogo.ts";
import { reconocerTelefono, repartirNumeros } from "./telefonos.ts";

// ============================================================================
// crm-importar-leads — conector hoja de Google → crm.leads (2026-07-20).
//
// La hoja "Leads AVANCE CORP — captura para CRM" (Drive de Miguel) corre un
// Apps Script con trigger de tiempo que empuja aquí las filas sin estado; esta
// función valida, deduplica por teléfono y entra por la PUERTA SQL del importador
// (crm.importar_lead_fn, F2.b [D-4]: los mismos candados y el mismo INSERT de
// siempre, con el veredicto como respuesta en vez de como error). Devuelve
// el resultado POR FILA y el script lo escribe en la columna "Estado
// importación" de la propia hoja (la hoja es la UI de rechazos).
//
// Auth en dos capas: verify_jwt=true (el script manda el anon key como Bearer)
// + secreto compartido en `x-importar-secret` (comparación de tiempo constante).
// El secreto vive en el ENV del edge (dashboard → Edge Functions → Secrets,
// clave CRM_IMPORTAR_SECRET) y en las Propiedades del Apps Script — NUNCA en
// el código (rotado 2026-07-21). Sin env la función falla CERRADA (401 todo).
// Rotar = nuevo valor en ambos lados; no hace falta redeploy.
//
// Reglas espejadas de la BD (CHECKs/triggers de crm.leads, verificados en prod):
//  - telefono / telefono_alternativo: celular peruano, fijo peruano o numero
//    internacional en E.164 (ver telefonos.ts). Los dos candidatos se juzgan
//    JUNTOS: basta uno bueno para que el lead entre; solo si NINGUNO sirve se
//    rechaza la fila. El movil se prefiere como identidad (WhatsApp).
//  - origen del catálogo · moneda PEN/USD · monto (0, 9_999_999_999.99] 2 dec
//  - dni 8 dígitos · genero F/M · fecha_nacimiento en [1900, 2100) y edad ≥ 18
//    (regla de capa app: se invierte capital, no hay producto para menores)
//  - consentimiento_fuente ≤ 80 chars
//  - vendedor destino debe tener perfil Y membresía CRM activos, con rol
//    vendedor|supervisor (guard de tenencia); si el correo no resuelve, entra SIN dueño
//    (cola "por repartir" — permitido en INSERT porque auth.uid() es null con
//    service_role) y el estado lo avisa.
//  - etapa siempre 'nuevo'; creado_por null = importación de sistema.
//
// Body: { filas: [{ fila, nombre, telefono, telefono_alternativo?, capital, moneda, canal, correo?,
//                   dni?, genero?, fecha_nacimiento?, distrito?, interes?,
//                   nota?, vendedor_correo?, autorizo?, fuente_consentimiento? }] }
// Resp: { resultados: [{ fila, resultado, estado }], conciliacion: {...} }.
// `estado` conserva el texto visible de siempre; `resultado` permite que la hoja
// concilie el lote sin inferir la categoría desde texto libre.
// ============================================================================

// Secreto compartido con el Apps Script de la hoja — SOLO del entorno.
// Debe ser 64 hex (openssl rand -hex 32). Si falta o no cumple el formato,
// secretoValido() rechaza todas las solicitudes (fail-closed): un valor débil no debe habilitar
// el conector por accidente.
const IMPORTAR_SECRET = Deno.env.get("CRM_IMPORTAR_SECRET") ?? "";
const SECRETO_BIEN_FORMADO = /^[0-9a-f]{64}$/i.test(IMPORTAR_SECRET);

const MAX_POR_LOTE = 200;
const MONTO_MAX = 9_999_999_999.99;
const EDAD_MINIMA = 18;

// Server-a-server (Apps Script): sin navegador no hay CORS real, pero se
// responde OPTIONS por higiene y se restringe a POST.
const CORS = {
  "Access-Control-Allow-Origin": "https://crm.miavance.com",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-importar-secret",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS, "Content-Type": "application/json" },
  });
}

/** Comparación de tiempo constante (evita timing attack sobre el secreto). */
function secretoValido(recibido: string | null): boolean {
  // Sin secreto (o mal formado) en el env, NADIE entra (fail-closed).
  if (!SECRETO_BIEN_FORMADO) return false;
  if (!recibido || recibido.length !== IMPORTAR_SECRET.length) return false;
  let diff = 0;
  for (let i = 0; i < IMPORTAR_SECRET.length; i++) {
    diff |= recibido.charCodeAt(i) ^ IMPORTAR_SECRET.charCodeAt(i);
  }
  return diff === 0;
}

const CORREO_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/** Etiquetas de la hoja → claves del CHECK leads_origen_check. */
const CANALES: Record<string, string> = {
  referido: "referido",
  landing: "landing",
  formulario: "formulario",
  wallking: "oficina", // label comercial del catálogo del CRM
  walking: "oficina",
  oficina: "oficina",
  otro: "otro",
  web: "web",
  campania: "campania",
  "campaña": "campania",
  whatsapp: "whatsapp",
};

const INTERES: Record<string, string> = {
  nuevo: "nuevo",
  renovacion: "renovacion",
  "renovación": "renovacion",
  upgrade: "upgrade",
};

/** DD/MM/AAAA o AAAA-MM-DD (Sheets reformatea a gusto) → ISO o null. */
function parseFecha(valor: string): string | null {
  const v = valor.trim();
  let d: number, m: number, a: number;
  let match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(v);
  if (match) {
    [d, m, a] = [Number(match[1]), Number(match[2]), Number(match[3])];
  } else {
    match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v);
    if (!match) return null;
    [a, m, d] = [Number(match[1]), Number(match[2]), Number(match[3])];
  }
  const fecha = new Date(Date.UTC(a, m - 1, d));
  if (
    fecha.getUTCFullYear() !== a || fecha.getUTCMonth() !== m - 1 ||
    fecha.getUTCDate() !== d
  ) return null;
  const iso = `${String(a).padStart(4, "0")}-${String(m).padStart(2, "0")}-${
    String(d).padStart(2, "0")
  }`;
  return iso;
}

function edadCumplida(isoNacimiento: string): number {
  // "Hoy" en calendario de LIMA (UTC-5, sin horario de verano). Sin el ajuste,
  // entre las 19:00 y 23:59 de Lima el edge ya está en el día UTC siguiente y
  // podría aceptar a alguien un día antes de cumplir 18 en su calendario local.
  const hoy = new Date(Date.now() - 5 * 60 * 60 * 1000);
  const nac = new Date(`${isoNacimiento}T00:00:00Z`);
  let edad = hoy.getUTCFullYear() - nac.getUTCFullYear();
  const mesDia = (hoy.getUTCMonth() - nac.getUTCMonth()) * 100 +
    (hoy.getUTCDate() - nac.getUTCDate());
  if (mesDia < 0) edad--;
  return edad;
}

/**
 * Capital de la hoja → número, con el ÚNICO formato aceptado: coma = millares,
 * punto = decimal (convención peruana y del CRM). Estricto a propósito: RECHAZA
 * (nunca reinterpreta ni redondea) los formatos ambiguos o con más de 2 decimales
 * — espejo de validacion.ts del CRM: mover de rango un capital es grave.
 *   OK:  "50000" · "50,000" · "50000.50" · "S/ 50,000.00" · "US$ 1,250.5"
 *   NO:  "5000.999" (3 dec) · "12,50" (millar mal puesto) · "50.000,00" (formato UE)
 */
function parseCapital(valor: string): number | null {
  const limpio = valor.replace(/US\$|S\/\.?|\$/gi, "").replace(/\s/g, "")
    .trim();
  if (limpio === "") return null;
  // Solo dígitos, comas de millar en grupos de 3, y a lo sumo un punto decimal
  // con 1-2 dígitos. Cualquier otra cosa NO matchea → null (rechazo, no arreglo).
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(limpio);
  if (!m) return null;
  const entero = m[1].replace(/,/g, "");
  const n = Number(m[2] != null ? `${entero}.${m[2]}` : entero);
  if (!Number.isFinite(n) || n <= 0 || n > MONTO_MAX) return null;
  // Guard canónico redundante (el regex ya limita a 2 decimales), por si acaso.
  if (Math.round(n * 100) / 100 !== n) return null;
  return n;
}

type FilaHoja = {
  fila?: number;
  nombre?: string;
  telefono?: string;
  telefono_alternativo?: string;
  capital?: string;
  moneda?: string;
  canal?: string;
  correo?: string;
  dni?: string;
  genero?: string;
  fecha_nacimiento?: string;
  distrito?: string;
  interes?: string;
  nota?: string;
  vendedor_correo?: string;
  autorizo?: string;
  fuente_consentimiento?: string;
};

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return json({ error: "Método no permitido" }, 405);

  if (!secretoValido(req.headers.get("x-importar-secret"))) {
    return json({ error: "No autorizado" }, 401);
  }

  let body: { filas?: FilaHoja[] };
  try {
    body = await req.json();
  } catch {
    return json({ error: "Body inválido" }, 400);
  }
  const filas = Array.isArray(body?.filas) ? body.filas : null;
  if (!filas || filas.length === 0) {
    return json({ error: "Sin filas que importar" }, 400);
  }
  if (filas.length > MAX_POR_LOTE) {
    return json({ error: `Máximo ${MAX_POR_LOTE} filas por lote` }, 400);
  }

  const admin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    { auth: { persistSession: false }, db: { schema: "crm" } },
  );

  // ── Pase 1: validar cada fila en memoria ───────────────────────────────────
  type Valida = {
    fila: number;
    telefono: string;
    insert: Record<string, unknown>;
    vendedorCorreo: string | null;
    avisos: string[];
  };
  type ResultadoFila = {
    fila: number;
    resultado: CategoriaResultadoImportacion;
    estado: string;
  };
  const resultados: ResultadoFila[] = [];
  const validas: Valida[] = [];
  const telefonosLote = new Set<string>();

  for (const f of filas) {
    const fila = typeof f.fila === "number" ? f.fila : -1;
    const rechazo = (motivo: string) =>
      resultados.push({
        fila,
        resultado: "rechazado",
        estado: `RECHAZADO: ${motivo}`,
      });

    const nombre = (f.nombre ?? "").trim();
    if (!nombre) {
      rechazo("falta el nombre");
      continue;
    }
    if (nombre.length > 160) {
      rechazo("nombre demasiado largo");
      continue;
    }

    // ⚠️ UN SOLO NUMERO BUENO BASTA (regla de Miguel, 2026-08-26: «si los dos
    // numeros estan mal, ahi si debe descartarlo»). Los dos candidatos de la
    // fila se juzgan JUNTOS: si el principal esta ilegible pero el segundo
    // sirve, ese pasa a ser la identidad y el lead ENTRA. Hasta hoy un teclazo
    // en la primera columna tiraba el lead entero teniendo el otro numero al
    // lado. El movil se prefiere para principal (es lo que responde WhatsApp);
    // un fijo solo sube a identidad cuando no hay ningun movil en la fila.
    const reparto = repartirNumeros([f.telefono, f.telefono_alternativo]);
    if (!reparto.principal) {
      rechazo(
        "ningún teléfono utilizable (celular peruano 9########, fijo peruano, o internacional con +código de país)",
      );
      continue;
    }
    const telefono = reparto.principal;
    if (telefonosLote.has(telefono)) {
      rechazo("teléfono repetido en la misma hoja");
      continue;
    }
    // El segundo numero ya no puede costar un lead: `repartirNumeros` lo devuelve
    // solo si sirve, y su ausencia nunca rechaza la fila. Lo que no se pudo leer
    // viaja como AVISO a la columna de estado de la hoja, que es donde se corrige.
    const alternativoRaw = (f.telefono_alternativo ?? "").trim();
    const alternativoDistinto = reparto.alternativo;
    // Lo que no se pudo leer NO se tira: viaja crudo para que un humano lo mire.
    const alternativoCrudo = reparto.alternativoCrudo;
    const principalRaw = (f.telefono ?? "").trim();
    const principalEraElDeSiempre =
      reconocerTelefono(principalRaw)?.e164 === telefono;

    const capital = parseCapital((f.capital ?? "").trim());
    if (capital === null) {
      rechazo(
        "capital inválido (número mayor a 0, formato coma=millar punto=decimal, máx 2 decimales)",
      );
      continue;
    }

    const monedaRaw = (f.moneda ?? "").trim().toUpperCase();
    const moneda = monedaRaw === "PEN" || monedaRaw === "SOLES"
      ? "PEN"
      : monedaRaw === "USD" || monedaRaw === "DOLARES" ||
          monedaRaw === "DÓLARES"
      ? "USD"
      : null;
    if (!moneda) {
      rechazo("moneda debe ser PEN o USD");
      continue;
    }

    // Solo claves PROPIAS: «Constructor» o «__proto__» en la hoja no deben caer en el
    // prototipo del objeto (Codex v5 #5: `origen` acababa siendo una función, JSON la
    // omitía y la fila cambiaba de categoría entre el INSERT directo y la puerta).
    const canal = etiquetaPropia(CANALES, (f.canal ?? "").trim().toLowerCase());
    if (!canal) {
      rechazo(
        "canal inválido (Referido / LANDING / FORMULARIO / Wallking / Otro)",
      );
      continue;
    }

    const correo = (f.correo ?? "").trim().toLowerCase() || null;
    if (correo && !CORREO_RE.test(correo)) {
      rechazo("correo inválido");
      continue;
    }

    // El DNI puede venir con separadores si Sheets lo trató como número
    // (p.ej. "45,687,364"): se quitan espacios y comas antes de exigir 8 dígitos.
    const dni = (f.dni ?? "").replace(/[\s,]/g, "") || null;
    if (dni && !/^\d{8}$/.test(dni)) {
      rechazo("DNI inválido (deben ser 8 dígitos)");
      continue;
    }

    const generoRaw = (f.genero ?? "").trim().toUpperCase();
    const genero = generoRaw === "F" || generoRaw === "M" ? generoRaw : null;
    if (generoRaw && !genero) {
      rechazo("género debe ser F o M");
      continue;
    }

    let fechaNacimiento: string | null = null;
    const fechaRaw = (f.fecha_nacimiento ?? "").trim();
    if (fechaRaw) {
      fechaNacimiento = parseFecha(fechaRaw);
      if (!fechaNacimiento) {
        rechazo("fecha de nacimiento inválida (usar DD/MM/AAAA)");
        continue;
      }
      if (fechaNacimiento < "1900-01-01" || fechaNacimiento >= "2100-01-01") {
        rechazo("fecha de nacimiento fuera de rango");
        continue;
      }
      if (edadCumplida(fechaNacimiento) < EDAD_MINIMA) {
        rechazo(`el lead debe ser mayor de ${EDAD_MINIMA} años`);
        continue;
      }
    }

    const interesRaw = (f.interes ?? "").trim().toLowerCase();
    const interes = interesRaw
      ? etiquetaPropia(INTERES, interesRaw) ?? null
      : null;
    if (interesRaw && !interes) {
      rechazo("interés inválido (Nuevo / Renovación / Upgrade)");
      continue;
    }

    // La hoja solo registra si hubo un SI explícito. Tanto NO como vacío dejan
    // el lead visible y repartible (`no_contactar = false`); esta integración no
    // activa ni hereda el bloqueo "No Insista" del CRM.
    const autorizacion = interpretarAutorizacionContacto(f.autorizo);
    if (!autorizacion.ok) {
      rechazo(autorizacion.error);
      continue;
    }
    const registrarConsentimiento = autorizacion.registrarConsentimiento;
    const fuente = (f.fuente_consentimiento ?? "").trim().slice(0, 80) || null;

    const avisos: string[] = [];
    if (!principalEraElDeSiempre) {
      avisos.push(
        principalRaw
          ? "el teléfono principal no se pudo leer → se usó el 2.º número"
          : "sin teléfono principal → se usó el 2.º número",
      );
    }
    if (alternativoRaw && !alternativoDistinto) {
      avisos.push(
        reconocerTelefono(alternativoRaw)
          ? "2.º número repetía al principal → no se guardó"
          : "2.º número ilegible → se guardó tal como llegó, para corregirlo",
      );
    }
    telefonosLote.add(telefono);
    validas.push({
      fila,
      telefono,
      vendedorCorreo: (f.vendedor_correo ?? "").trim().toLowerCase() || null,
      avisos,
      insert: {
        nombre_completo: nombre,
        telefono,
        telefono_alternativo: alternativoDistinto,
        telefono_alternativo_crudo: alternativoCrudo,
        correo,
        dni,
        genero,
        fecha_nacimiento: fechaNacimiento,
        distrito: (f.distrito ?? "").trim().slice(0, 120) || null,
        origen: canal,
        etapa: "nuevo",
        monto_estimado: capital,
        moneda,
        categoria_interes: interes,
        nota: (f.nota ?? "").trim().slice(0, 2000) || null,
        no_contactar: false,
        consentimiento_en: registrarConsentimiento
          ? new Date().toISOString()
          : null,
        consentimiento_fuente: registrarConsentimiento ? fuente : null,
        vendedor_id: null,
        asignado_supervisor_id: null,
        activo: true,
      },
    });
  }

  if (validas.length > 0) {
    // ── Pase 2 (F2.b [D-4] v4, Codex #2): SIN dedup previo contra la BD ────────
    // Antes se consultaba `leads` por teléfono vivo y esas filas se cerraban como
    // DUPLICADO sin llegar a la base. Con la identidad encendida eso se saltaba el
    // reingreso: la persona reconocida cuyo lead vivo tiene el MISMO teléfono debe
    // recibir «ya es cliente» y su reingreso, no «duplicado». Ahora decide la puerta
    // (índice único de teléfono/DNI vivo → duplicado; trigger de identidad → ya
    // cliente / no insistir). El dedup dentro del mismo lote sigue en el pase 1.

    // ── Pase 3: resolver destino por el rol CRM efectivo canónico ───────────
    const correosVendedor = [
      ...new Set(validas.map((v) => v.vendedorCorreo).filter(Boolean)),
    ] as string[];
    const vendedorPorCorreo = new Map<string, string>();
    if (correosVendedor.length > 0) {
      const { data: destinos, error: errDestinos } = await admin.rpc(
        "destinos_importacion_por_correo_fn",
        { p_correos: correosVendedor },
      );
      // Un fallo aquí (permisos/contrato/servicio) NO debe leerse como "vendedor no
      // encontrado" e importar todo sin dueño: se corta con 500 ANTES de cualquier
      // insert y el Apps Script reintenta el lote como "ERROR temporal".
      if (errDestinos) {
        return json({
          error: `Error resolviendo vendedores: ${errDestinos.message}`,
        }, 500);
      }
      try {
        for (const [correo, perfilId] of indexarDestinosImportacion(destinos)) {
          vendedorPorCorreo.set(correo, perfilId);
        }
      } catch (error) {
        const detalle = error instanceof Error
          ? error.message
          : "respuesta inválida";
        return json({ error: `Error resolviendo vendedores: ${detalle}` }, 500);
      }
    }

    // F2.b [D-4]: la bandera de identidad ya no se lee aquí: la puerta SQL decide con la
    // identidad que haya (apagada = el INSERT de siempre; encendida = persona reconocida,
    // reingreso en su lead, vetos), sin parsear errores.

    // ── Pase 4: insertar UNA a una (un lead malo no tumba el lote) ───────────
    for (const v of validas) {
      if (v.vendedorCorreo) {
        const id = vendedorPorCorreo.get(v.vendedorCorreo);
        if (id) v.insert.vendedor_id = id;
        else v.avisos.push("vendedor no encontrado → quedó por repartir");
      }
      // F2.b [D-4]: la puerta SQL (solo service_role, sin sesión) hace el INSERT de siempre bajo
      // los candados en el orden total y devuelve el veredicto; si «ya es cliente» por identidad,
      // el reingreso queda anotado en su lead dentro de la misma transacción.
      const { data: respuesta, error: errPuerta, status: statusPuerta } =
        await admin.rpc(
          "importar_lead_fn",
          { p_fila: { ...v.insert, fila: v.fila } },
        );
      if (errPuerta) {
        // Errores que la puerta deja subir (datos inválidos, destino que no puede recibir
        // leads, timeouts): la misma clasificación de siempre (definitivo vs temporal). Si la
        // puerta no está (reversa, caché rancia, EXECUTE perdido) la fila se reintenta, no se congela.
        const clasificacion = clasificarErrorPuerta(errPuerta, statusPuerta);
        resultados.push({
          fila: v.fila,
          resultado: clasificacion.resultado,
          estado: clasificacion.estado,
        });
        continue;
      }
      const clasificacion = clasificarRespuestaPuerta(
        respuesta as RespuestaPuerta,
      );
      if (clasificacion.resultado !== "importado") {
        resultados.push({
          fila: v.fila,
          resultado: clasificacion.resultado,
          estado: clasificacion.estado,
        });
        continue;
      }
      const sufijo = v.avisos.length > 0 ? ` (${v.avisos.join("; ")})` : "";
      resultados.push({
        fila: v.fila,
        resultado: "importado",
        estado: `IMPORTADO ✓${sufijo}`,
      });
    }
  }

  resultados.sort((a, b) => a.fila - b.fila);
  const conteo = {
    importadas: 0,
    duplicadas: 0,
    ya_clientes: 0,
    rechazadas: 0,
    errores_temporales: 0,
  };
  for (const r of resultados) {
    if (r.resultado === "importado") conteo.importadas++;
    else if (r.resultado === "duplicado") conteo.duplicadas++;
    else if (r.resultado === "ya_cliente") conteo.ya_clientes++;
    else if (r.resultado === "rechazado") conteo.rechazadas++;
    else conteo.errores_temporales++;
  }
  return json({
    resultados,
    conciliacion: {
      solicitadas: filas.length,
      confirmadas: resultados.length,
      no_importadas: filas.length - conteo.importadas,
      ...conteo,
    },
  });
});

export type AutorizacionContactoHoja =
  | { ok: true; registrarConsentimiento: boolean }
  | { ok: false; error: string };

/**
 * La respuesta de la hoja es informativa para el registro de consentimiento.
 * Por decisión operativa, nunca activa `no_contactar`: todo lead importado debe
 * quedar visible y repartible. El bloqueo "No Insista", si se usa, se gestiona
 * exclusivamente dentro del CRM y no se hereda desde esta integración.
 */
export function interpretarAutorizacionContacto(
  valor: string | undefined,
): AutorizacionContactoHoja {
  const normalizado = (valor ?? "").trim().toUpperCase();

  if (normalizado === "") {
    return { ok: true, registrarConsentimiento: false };
  }
  if (
    normalizado === "SI" || normalizado === "SÍ" || normalizado === "S"
  ) {
    return { ok: true, registrarConsentimiento: true };
  }
  if (normalizado === "NO" || normalizado === "N") {
    return { ok: true, registrarConsentimiento: false };
  }

  return {
    ok: false,
    error:
      "¿Autorizó contacto? debe ser SI o NO (vacío = sin registrar consentimiento)",
  };
}

export type DestinoImportacion = {
  correo: string;
  perfil_id: string;
};

/**
 * Convierte exclusivamente la salida del RPC canónico en el índice usado por
 * el importador. Cualquier colisión ambigua falla cerrada antes de insertar.
 */
export function indexarDestinosImportacion(
  filas: unknown,
): Map<string, string> {
  if (!Array.isArray(filas)) {
    throw new Error("contrato de destinos inválido");
  }

  const destinos = new Map<string, string>();
  for (const fila of filas) {
    if (
      typeof fila !== "object" || fila === null ||
      typeof (fila as Partial<DestinoImportacion>).correo !== "string" ||
      typeof (fila as Partial<DestinoImportacion>).perfil_id !== "string"
    ) {
      throw new Error("contrato de destinos inválido");
    }

    const correo = (fila as DestinoImportacion).correo.trim().toLowerCase();
    const perfilId = (fila as DestinoImportacion).perfil_id.trim();
    if (!correo || !perfilId) {
      throw new Error("contrato de destinos inválido");
    }

    const previo = destinos.get(correo);
    if (previo !== undefined && previo !== perfilId) {
      throw new Error("correo de destino ambiguo");
    }
    destinos.set(correo, perfilId);
  }
  return destinos;
}

export type CategoriaResultadoImportacion =
  | "importado"
  | "duplicado"
  | "ya_cliente"
  | "rechazado"
  | "error_temporal";

export type ResultadoImportacion = {
  resultado: CategoriaResultadoImportacion;
  estado: string;
  /** Solo en `ya_cliente`: el lead canónico de la persona (para registrar el reingreso). */
  lead_id?: string;
  asesor?: string;
};

type ErrorPostgrestMinimo = {
  code?: string | null;
  message?: string | null;
  details?: string | null;
};

/**
 * Veredicto de disponibilidad que el servidor adjunta en DETAIL (P0481/P0429)
 * como JSON. Devuelve null si no hay JSON legible.
 */
export function veredictoDeError(
  error: ErrorPostgrestMinimo,
): Record<string, unknown> | null {
  const crudo = String(error?.details ?? "").trim();
  if (!crudo.startsWith("{")) return null;
  try {
    const v = JSON.parse(crudo);
    return v && typeof v === "object" ? (v as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

const CODIGOS_TEMPORALES = new Set([
  "55P03", // lock_not_available
  "57014", // query_canceled / timeout
  "57P01", // admin_shutdown
  "57P02", // crash_shutdown
  "57P03", // cannot_connect_now
]);

/**
 * Convierte un fallo de INSERT en una categoría estable para la hoja.
 *
 * Las restricciones/datos inválidos son definitivos y requieren corregir la fila.
 * Los fallos de conexión, concurrencia, capacidad o servidor se reintentan: nunca
 * deben congelarse en la hoja como un rechazo permanente. Una carrera contra el
 * índice único de teléfono es un duplicado, no un error crudo de Postgres.
 */
export function clasificarErrorInsercion(
  error: ErrorPostgrestMinimo,
  status?: number | null,
): ResultadoImportacion {
  const codigo = String(error?.code ?? "").trim().toUpperCase();
  if (codigo === "23505") {
    return {
      resultado: "duplicado",
      estado: "DUPLICADO: ya existe en el CRM",
    };
  }

  // F2.b b1 (identidad unificada, con la bandera resolver_en_puertas encendida):
  // la BD reconoce a la PERSONA por su documento. «Ya es cliente» no es un
  // rechazo: es un reingreso que se registra en SU lead. «No insistir» sí lo es.
  if (codigo === "P0481") {
    const v = veredictoDeError(error);
    if (v?.estado === "ya_es_cliente" && v?.via === "identidad") {
      const asesor = typeof v.asesor === "string" ? v.asesor : "";
      // El estado NO afirma todavía «registrado»: eso lo compone el edge solo
      // después de que la RPC de reingreso haya tenido éxito.
      return {
        resultado: "ya_cliente",
        estado: `YA ES CLIENTE${asesor ? ` (asesor: ${asesor})` : ""}`,
        lead_id: typeof v.lead_id === "string" ? v.lead_id : undefined,
        asesor: asesor || undefined,
      };
    }
    const estado = typeof v?.estado === "string" ? v.estado : "no disponible";
    return {
      resultado: "rechazado",
      estado: `RECHAZADO: contacto ${estado.replace(/_/g, " ")}`,
    };
  }
  if (codigo === "P0429") {
    return {
      resultado: "rechazado",
      estado: "RECHAZADO: la persona tiene la restricción «No insistir»",
    };
  }

  const clase = codigo.slice(0, 2);
  const statusTemporal = status === 0 || status === 408 || status === 425 ||
    status === 429 || (typeof status === "number" && status >= 500);
  const codigoTemporal = CODIGOS_TEMPORALES.has(codigo) ||
    ["08", "40", "53", "58", "XX"].includes(clase);

  if (statusTemporal || codigoTemporal) {
    return {
      resultado: "error_temporal",
      estado:
        "ERROR temporal: el CRM no confirmó la importación — se reintenta solo",
    };
  }

  const detalle = String(error?.message ?? "el CRM rechazó los datos")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 120) || "el CRM rechazó los datos";
  return {
    resultado: "rechazado",
    estado: `RECHAZADO: ${detalle}`,
  };
}

/**
 * F2.b [D-4] (auditor A1): un error de la PUERTA que no es un veredicto sobre la fila —la RPC no existe
 * (PGRST202 / 42883: reversa aplicada o caché de PostgREST rancia), el EXECUTE se perdió (42501) o un 404—
 * es un problema del CRM, no de la fila: TEMPORAL, para que la hoja la reintente en vez de congelarla como
 * RECHAZADA. Cualquier otro error sigue la clasificación de siempre (definitivo vs temporal).
 */
export function clasificarErrorPuerta(
  error: ErrorPostgrestMinimo,
  status?: number | null,
): ResultadoImportacion {
  const codigo = String(error?.code ?? "").trim().toUpperCase();
  if (
    codigo === "PGRST202" || codigo === "42883" || codigo === "42501" ||
    status === 404
  ) {
    return {
      resultado: "error_temporal",
      estado:
        "ERROR temporal: la puerta del importador no está disponible en el CRM — se reintenta solo",
    };
  }
  return clasificarErrorInsercion(error, status);
}

// ── F2.b [D-4] (bloque 3): el importador entra por la puerta SQL crm.importar_lead_fn ───────────────────────────────
// La puerta hace el MISMO INSERT que hacía este edge y devuelve un veredicto en vez de una excepción. Los textos que
// llegan a la hoja son los mismos de siempre: aquí solo cambia de dónde sale la categoría.

export type ReingresoPuerta = {
  ok?: boolean;
  repetido?: boolean;
  actividad_id?: string;
  error?: string;
} | null;

/** F2.b [D-20]: lo que la puerta hizo con la solicitud de un cliente que ya no tiene lead vivo. */
export type SolicitudPuerta = {
  ok?: boolean;
  repetido?: boolean;
  actividad_id?: string;
  tarea_id?: string;
  sin_tarea?: boolean;
  sin_ficha?: boolean;
  vetado?: boolean;
  error?: string;
} | null;

export type RespuestaPuerta = {
  resultado: "importado" | "duplicado" | "ya_cliente" | "rechazado";
  lead_id?: string | null;
  veredicto?: Record<string, unknown> | null;
  reingreso?: ReingresoPuerta;
  solicitud?: SolicitudPuerta;
};

/** Texto de rechazo a partir del veredicto (el mismo que hoy sale del DETAIL del INSERT). */
export function textoRechazoDeVeredicto(
  veredicto: Record<string, unknown> | null | undefined,
): string {
  const estado = typeof veredicto?.estado === "string"
    ? veredicto.estado
    : "no disponible";
  // P0429 (trigger 000, identidad encendida): la PERSONA tiene «No insistir».
  if (estado === "no_contactar" && veredicto?.via === "identidad") {
    return "RECHAZADO: la persona tiene la restricción «No insistir»";
  }
  return `RECHAZADO: contacto ${estado.replace(/_/g, " ")}`;
}

/**
 * Convierte la respuesta de crm.importar_lead_fn en la categoría estable de la hoja.
 * `ya_cliente` compone además el texto del reingreso (registrado / no se pudo anotar), que antes componía el edge tras
 * llamar aparte a registrar_reingreso_lead_fn.
 */
const CATEGORIAS_PUERTA = new Set([
  "importado",
  "duplicado",
  "ya_cliente",
  "rechazado",
]);

export function clasificarRespuestaPuerta(
  r: RespuestaPuerta | null | undefined,
): ResultadoImportacion {
  // Solo las cuatro categorías del contrato; cualquier otra cosa (una versión de
  // la puerta que este edge no conoce) es temporal, nunca un rechazo (Codex v3 #4).
  if (
    !r || typeof r !== "object" || typeof r.resultado !== "string" ||
    !CATEGORIAS_PUERTA.has(r.resultado)
  ) {
    return {
      resultado: "error_temporal",
      estado:
        "ERROR temporal: el CRM no confirmó la importación — se reintenta solo",
    };
  }
  if (r.resultado === "importado") {
    return {
      resultado: "importado",
      estado: "IMPORTADO ✓",
      lead_id: r.lead_id ?? undefined,
    };
  }
  if (r.resultado === "duplicado") {
    return { resultado: "duplicado", estado: "DUPLICADO: ya existe en el CRM" };
  }
  if (r.resultado === "ya_cliente") {
    const v = r.veredicto ?? {};
    const asesor = typeof v.asesor === "string" ? v.asesor : "";
    const base = `YA ES CLIENTE${asesor ? ` (asesor: ${asesor})` : ""}`;
    const lead_id = typeof r.lead_id === "string" ? r.lead_id : undefined;
    let estado = base;
    if (r.reingreso && r.reingreso.ok === true) {
      // `repetido`: la hoja reenvió la misma fila (perdió la confirmación) y la
      // puerta reconoció el reingreso ya anotado en las últimas 24 h (v5).
      estado = r.reingreso.repetido === true
        ? `${base}: reingreso ya anotado en su ficha`
        : `${base}: reingreso registrado en su ficha`;
    } else if (r.reingreso && typeof r.reingreso.error === "string") {
      estado = `${base}: NO se pudo anotar el reingreso en su ficha (${
        r.reingreso.error.slice(0, 60)
      })`;
    } else if (r.solicitud) {
      // F2.b [D-20] (auditor A3): el cliente ya no tiene lead vivo, así que la solicitud va a su ficha y a la agenda
      // de su analista. Sin esto la hoja decía «YA ES CLIENTE» tanto si quedó tarea como si no quedó NADA, que es
      // justo el agujero que D-20 viene a cerrar.
      const s = r.solicitud;
      if (s.ok === true && s.repetido === true) {
        estado = `${base}: solicitud ya anotada en su ficha`;
      } else if (s.ok === true && s.sin_tarea === true) {
        estado = `${base}: solicitud anotada en su ficha, SIN analista para la tarea`;
      } else if (s.ok === true) {
        estado = `${base}: solicitud anotada y tarea para su analista`;
      } else if (s.vetado === true) {
        estado = `${base}: no se registra seguimiento («No insistir»)`;
      } else if (s.sin_ficha === true) {
        estado = `${base}: NO se pudo anotar (nadie a cargo de este cliente)`;
      } else {
        estado = `${base}: NO se pudo anotar la solicitud${
          typeof s.error === "string" ? ` (${s.error.slice(0, 60)})` : ""
        }`;
      }
    }
    return {
      resultado: "ya_cliente",
      estado,
      lead_id,
      asesor: asesor || undefined,
    };
  }
  return {
    resultado: "rechazado",
    estado: textoRechazoDeVeredicto(r.veredicto),
  };
}

// Catálogos de la hoja (canal, interés): la etiqueta se busca SOLO entre las claves
// PROPIAS. «Constructor» o «__proto__» escritos en la hoja no deben caer en el
// prototipo del objeto (Codex v5 #5: `origen` acababa siendo una función, JSON la
// omitía al serializar y la fila cambiaba de categoría entre el INSERT directo —que
// tomaba el DEFAULT— y la puerta —que recibía NULL—).

export function etiquetaPropia(
  catalogo: Record<string, string>,
  clave: string,
): string | undefined {
  return Object.hasOwn(catalogo, clave) ? catalogo[clave] : undefined;
}

/**
 * LA REGLA DEL TELEFONO, en un solo sitio y probada.
 * ────────────────────────────────────────────────────────────────────────────
 * Vivia dentro de index.ts, que no es testeable (tiene un `Deno.serve` en el
 * ambito del modulo, asi que importarlo levanta un servidor). Este modulo es el
 * ORIGINAL; sus gemelos —`app/src/lib/validacion.ts` en el front,
 * `telefonoPeru()` en el puente y el CHECK `leads_telefono_alternativo_formato`
 * en la base— tienen que decir lo mismo. Cambiar uno sin los otros es como se
 * pierde un lead en silencio.
 *
 * DECISIONES DE MIGUEL (2026-08-26):
 *   · «que los leads vengan con sus dos numeros si o si»
 *   · «si los dos numeros estan mal, ahi si debe descartarlo» → basta UN numero
 *     bueno para que el lead entre al CRM
 *   · «debe reconocer formatos de numero a nivel mundial»
 *
 * COMO SE RECONOCE UN NUMERO DEL MUNDO. Sin libphonenumber: no existe en el
 * Apps Script del puente ni dentro de un CHECK de Postgres, y la regla tiene que
 * ser LA MISMA en las cuatro capas o vuelve el silencio. Se usa E.164, que es el
 * estandar que define que es un numero de telefono en el planeta:
 *
 *   · Si el texto trae `+` o empieza por `00` (prefijo internacional), es
 *     INTERNACIONAL: entre 8 y 15 digitos en total, primer digito 1-9.
 *   · Si no, se asume PERU, que es de donde viene el 99% del negocio: nueve
 *     digitos empezando en 9 es celular; ocho digitos es fijo.
 *   · Un numero que dice ser peruano (empieza por 51) NO se acepta a la ligera:
 *     tiene que tener la forma peruana exacta. Si no, `+51123` entraria como
 *     "internacional valido" y nadie podria llamarlo nunca.
 */

/** Tipo de numero reconocido. `null` = no es un telefono. */
export type ClaseTelefono = "celular_pe" | "fijo_pe" | "internacional";

export type TelefonoReconocido = {
  /** Canonico E.164: `+` y solo digitos. Es lo que se guarda. */
  e164: string;
  clase: ClaseTelefono;
  /** Sirve para WhatsApp y para recibir SMS. Un fijo, no. */
  movil: boolean;
};

const E164_MIN = 8;  // el numero mas corto del mundo con codigo de pais
const E164_MAX = 15; // tope del estandar E.164

/**
 * Reconoce un numero escrito de cualquier manera. Devuelve `null` si no hay
 * telefono que rescatar.
 *
 * Acepta la basura tipografica que llega de verdad desde Sheets y desde los
 * formularios: espacios, guiones, parentesis, puntos, y la COMA que mete Sheets
 * cuando trata el celular como numero ("964,262,777").
 */
export function reconocerTelefono(valor: string | null | undefined): TelefonoReconocido | null {
  const bruto = (valor ?? "").trim();
  if (!bruto) return null;
  // Un correo metido en la columna de telefono no es un telefono roto: es otro
  // dato en el sitio equivocado. Cuenta aparte y no ensucia lo que se pierde.
  if (bruto.includes("@")) return null;
  // Las letras NO descartan: "p:+51910585900" es una fila real del origen y el
  // numero esta ahi entero. Se juzga por los digitos que quedan.
  const digitos = bruto.replace(/\D/g, "");
  if (!digitos) return null;

  // ¿Viene marcado como internacional? El `+` explicito o el 00 de salida.
  const marcadoInternacional = bruto.trimStart().startsWith("+") || digitos.startsWith("00");
  const sinSalida = digitos.replace(/^00/, "");

  // ── Peru, se declare o no ────────────────────────────────────────────────
  // Todo lo que empieza por 51 se juzga con la vara peruana: si no tiene la
  // forma exacta, no es un numero peruano y tampoco vale como "internacional".
  const nacional = sinSalida.startsWith("51") ? sinSalida.slice(2) : sinSalida;
  const declaraPeru = sinSalida.startsWith("51") && nacional.length >= 8;

  if (declaraPeru || !marcadoInternacional) {
    const n = declaraPeru ? nacional : sinSalida;
    if (/^9\d{8}$/.test(n)) return { e164: `+51${n}`, clase: "celular_pe", movil: true };
    // ⚠️ UN FIJO EXIGE MARCA. El nacional de un fijo peruano tiene ocho digitos
    // (Lima 1+siete, provincias 84+seis)… y el DNI peruano TAMBIEN tiene ocho.
    // Aceptar ocho digitos pelados convertia todo DNI en un telefono: el
    // buscador ofrecia «verificar disponibilidad» sobre un documento y el
    // formulario daba por bueno un DNI escrito en la casilla del celular. Lo
    // cazaron tres pruebas del front. Asi que un fijo solo se reconoce cuando
    // viene MARCADO como telefono: con `+51`/`0051`, o con el 0 de larga
    // distancia con el que la gente escribe su fijo de verdad (014457890).
    const marcaDeFijo = declaraPeru || n.startsWith("0");
    const sinCero = n.startsWith("0") ? n.slice(1) : n;
    if (marcaDeFijo && /^[1-8]\d{7}$/.test(sinCero)) {
      return { e164: `+51${sinCero}`, clase: "fijo_pe", movil: false };
    }
    // Dijo ser peruano y no lo es: se acaba aqui, no cae al cajon internacional.
    if (declaraPeru) return null;
    // Sin `+` y sin forma peruana: no hay pais que suponer. No se inventa uno.
    if (!marcadoInternacional) return null;
  }

  // ── El resto del mundo ───────────────────────────────────────────────────
  // E.164 puro. No se valida el codigo de pais contra una lista: mantenerla al
  // dia en cuatro capas es una deuda peor que aceptar un numero raro, y el
  // largo minimo ya deja fuera lo que no es un telefono.
  if (
    sinSalida.length >= E164_MIN && sinSalida.length <= E164_MAX &&
    /^[1-9]\d*$/.test(sinSalida)
  ) {
    // Movil o fijo es indecidible fuera de Peru sin libphonenumber. Se asume
    // MOVIL: equivocarse hacia "se puede escribir por WhatsApp" ofrece un boton
    // que quiza no responda; al reves, esconderia el unico canal que hay.
    return { e164: `+${sinSalida}`, clase: "internacional", movil: true };
  }
  return null;
}

/**
 * El telefono PRINCIPAL del lead: su identidad (dedup, reparto, conversion).
 *
 * Se sigue prefiriendo un MOVIL: es lo que responde WhatsApp, que es como se
 * trabaja aqui. Un fijo solo llega a principal cuando no hay ningun movil en la
 * fila — antes de eso, la alternativa era descartar al lead entero, y un lead
 * al que se puede llamar vale mas que un boton de WhatsApp que funcione.
 */
export function normalizarTelefono(valor: string): string | null {
  const r = reconocerTelefono(valor);
  return r && r.movil ? r.e164 : null;
}

/** El SEGUNDO numero: cualquier telefono reconocible, movil o fijo. */
export function normalizarTelefonoAlternativo(valor: string): string | null {
  const r = reconocerTelefono(valor);
  return r ? r.e164 : null;
}

/** Tope de cordura del texto crudo — espejo del CHECK de la base. */
export const CRUDO_MAX = 40;

export type RepartoNumeros = {
  /** La identidad del lead. `null` = ningun numero servia → se descarta. */
  principal: string | null;
  /** El segundo canal, canonico y marcable. */
  alternativo: string | null;
  /**
   * Lo que la persona escribio y NO se pudo entender como telefono. Existe para
   * que nada se pierda en silencio (decision de Miguel, 2026-08-26). Excluyente
   * con `alternativo`, igual que en la base: si hubo un segundo numero legible,
   * esto es null.
   */
  alternativoCrudo: string | null;
};

/**
 * De todos los numeros que trae una fila, cual es el principal, cual el segundo
 * y que queda sin poder leerse. Devuelve `principal: null` solo cuando NINGUNO
 * sirve — que es el unico caso en que el lead se descarta.
 *
 * Orden: el primer MOVIL manda (identidad); el segundo es el siguiente numero
 * DISTINTO, sea movil o fijo. Si no hay ningun movil, el primer fijo se sube a
 * principal en vez de tirar el lead.
 *
 * `alternativoCrudo` no distingue de que casilla salio el texto ilegible: es «el
 * otro dato de contacto que la persona escribio y no supimos leer». Un correo
 * metido en la casilla del telefono NO cuenta — es otro dato en el sitio
 * equivocado, no un numero perdido, y contarlo inflaria lo que se muestra como
 * «sin validar».
 */
export function repartirNumeros(
  candidatos: (string | null | undefined)[],
): RepartoNumeros {
  const vistos: TelefonoReconocido[] = [];
  const ilegibles: string[] = [];
  for (const c of candidatos) {
    const bruto = (c ?? "").trim();
    if (!bruto) continue;
    const r = reconocerTelefono(bruto);
    if (r) {
      if (!vistos.some((v) => v.e164 === r.e164)) vistos.push(r);
    } else if (!bruto.includes("@")) {
      ilegibles.push(bruto);
    }
  }
  if (vistos.length === 0) {
    return { principal: null, alternativo: null, alternativoCrudo: null };
  }

  const iPrincipal = vistos.findIndex((v) => v.movil);
  const principal = iPrincipal >= 0 ? vistos[iPrincipal] : vistos[0];
  const alternativo = vistos.find((v) => v.e164 !== principal.e164) ?? null;
  return {
    principal: principal.e164,
    alternativo: alternativo ? alternativo.e164 : null,
    // Excluyentes, como en la base: un lead no puede mostrar dos «segundos
    // numeros» distintos, o la ficha tendria que elegir cual pinta.
    alternativoCrudo: alternativo || ilegibles.length === 0
      ? null
      : ilegibles[0].slice(0, CRUDO_MAX),
  };
}
